import { createFileRoute, Link } from "@tanstack/react-router";
import { useSuspenseQuery } from "@tanstack/react-query";
import { trpc } from "@/utils/trpc";
import { requirePermission } from "@/utils/require-permission";
import { z } from "zod";
import { useMemo } from "react";
import {
  IconUsers,
  IconTrendingUp,
  IconClipboardCheck,
  IconAward,
  IconEdit,
  IconBookUpload,
  IconEye,
} from "@tabler/icons-react";
import { Button } from "@/components/ui/button";

export const Route = createFileRoute(
  "/(core)/back-office/pelatihan/$pelatihanId/overview",
)({
  params: z.object({
    pelatihanId: z.string(),
  }),
  beforeLoad: async ({ context }) =>
    await requirePermission(context, { permission: "pelatihan.view" }),
  component: OverviewTab,
});

const statusBadge: Record<string, { label: string; cls: string }> = {
  enrolled: { label: "Terdaftar", cls: "bg-slate-100 text-slate-600" },
  in_progress: { label: "Berjalan", cls: "bg-blue-100 text-blue-700" },
  completed: { label: "Selesai", cls: "bg-emerald-100 text-emerald-700" },
  failed: { label: "Gagal", cls: "bg-red-100 text-red-700" },
  expired: { label: "Kedaluwarsa", cls: "bg-amber-100 text-amber-700" },
};

function ProgressBar({ value }: { value: number }) {
  return (
    <div className="flex min-w-[100px] items-center gap-2">
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-slate-100">
        <div
          className="h-full rounded-full bg-blue-500 transition-all"
          style={{ width: `${value}%` }}
        />
      </div>
      <span className="w-8 shrink-0 text-right text-xs font-semibold text-slate-500">
        {value}%
      </span>
    </div>
  );
}

function OverviewTab() {
  const { pelatihanId } = Route.useParams();

  // Fetch Pelatihan details
  const { data: pelatihan } = useSuspenseQuery(
    trpc.pelatihan.base.getPelatihanById.queryOptions({ id: pelatihanId }),
  );

  // Fetch Pelatihan Statistics & Recent Activity
  const { data: stats } = useSuspenseQuery(
    trpc.pelatihan.base.getPelatihanStats.queryOptions({ id: pelatihanId }),
  );

  // Fetch Learning Structure Modules & Materials
  const { data: materialsData } = useSuspenseQuery(
    trpc.pelatihan.materials.getMaterialsAndModules.queryOptions({
      pelatihanId,
    }),
  );

  const flatMaterialsList = useMemo(() => {
    if (!materialsData) return [];
    const list: {
      id: string;
      title: string;
      type: string;
      moduleTitle: string;
    }[] = [];

    materialsData.modules.forEach((mod) => {
      mod.materials.forEach((mat) => {
        list.push({
          id: mat.id,
          title: mat.title,
          type: mat.type,
          moduleTitle: mod.title,
        });
      });
    });

    materialsData.orphanMaterials.forEach((mat) => {
      list.push({
        id: mat.id,
        title: mat.title,
        type: mat.type,
        moduleTitle: "Tanpa Modul",
      });
    });

    return list;
  }, [materialsData]);

  if (!pelatihan || !stats) return null;

  const isPublished = pelatihan.status === "published";

  const statsList = [
    {
      key: "peserta",
      label: "Total Peserta",
      value: stats.totalPeserta.toString(),
      sub: `+${stats.totalPesertaBaru} baru bulan ini`,
      positive: stats.totalPesertaBaru > 0 ? true : null,
      icon: IconUsers,
      color: "text-blue-600",
      bg: "bg-blue-50",
    },
    {
      key: "progress",
      label: "Progress Rata-rata",
      value: `${stats.avgProgress}%`,
      sub: "rata-rata penyelesaian",
      positive: null,
      icon: IconTrendingUp,
      color: "text-emerald-600",
      bg: "bg-emerald-50",
    },
    {
      key: "pretest",
      label: "Nilai Pre-Test",
      value: stats.avgPretest.toString(),
      sub: "rata-rata peserta",
      positive: null,
      icon: IconClipboardCheck,
      color: "text-amber-600",
      bg: "bg-amber-50",
    },
    {
      key: "posttest",
      label: "Nilai Post-Test",
      value: stats.avgPosttest.toString(),
      sub: "rata-rata peserta",
      positive: stats.avgPosttest >= 70 ? true : null,
      icon: IconAward,
      color: "text-violet-600",
      bg: "bg-violet-50",
    },
  ];

  return (
    <div className="space-y-4">
      {/* Unpublished Banner */}
      {!isPublished && (
        <div className="flex min-h-[220px] flex-col items-center justify-center gap-3 rounded-xl border border-[#E2E8F0] bg-white p-8 text-center">
          <div className="mb-2 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100">
            <IconBookUpload className="size-8 text-slate-400" />
          </div>
          <p className="text-lg font-bold text-[#4D4D4D]">
            {pelatihan.type === "bimtek"
              ? "Bimtek belum terpublish!"
              : pelatihan.type === "webinar"
                ? "Webinar belum terpublish!"
                : "E-learning belum terpublish!"}
          </p>
          <p className="text-sm text-[#768094]">
            Publish{" "}
            {pelatihan.type === "bimtek"
              ? "bimtek"
              : pelatihan.type === "webinar"
                ? "webinar"
                : "e-learning"}{" "}
            agar bisa di akses pengguna!
          </p>
          <Link
            to="/back-office/pelatihan/$pelatihanId/edit"
            params={{ pelatihanId }}
          >
            <Button className="mt-2 bg-[#1061D6] px-6 font-semibold text-white hover:bg-blue-700">
              Publish Sekarang
            </Button>
          </Link>
        </div>
      )}

      {/* Stats Grid */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {statsList.map((stat) => (
          <div
            key={stat.key}
            className="flex items-center gap-4 rounded-xl border border-[#E2E8F0] bg-white p-5 shadow-[0px_1px_2px_0px_rgba(15,23,42,0.04),0px_2px_6px_0px_rgba(15,23,42,0.06)]"
          >
            <div className={`rounded-xl p-3 ${stat.bg} shrink-0`}>
              <stat.icon className={`size-5 ${stat.color}`} />
            </div>
            <div className="min-w-0">
              <p className="truncate text-xs font-medium text-[#768094]">
                {stat.label}
              </p>
              <p className="mt-0.5 text-2xl leading-tight font-bold text-[#4D4D4D]">
                {stat.value}
              </p>
              <p
                className={`mt-0.5 text-[10px] font-medium ${
                  stat.positive === true
                    ? "text-emerald-600"
                    : stat.positive === false
                      ? "text-red-500"
                      : "text-[#768094]"
                }`}
              >
                {stat.sub}
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Two-column layout: Info + Struktur */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
        {/* Informasi Course */}
        <div className="rounded-xl border border-[#E2E8F0] bg-white p-5 shadow-[0px_1px_2px_0px_rgba(15,23,42,0.04),0px_2px_6px_0px_rgba(15,23,42,0.06)] lg:col-span-2">
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-sm font-bold text-[#4D4D4D]">
              Informasi Course
            </h3>
            <Link
              to="/back-office/pelatihan/$pelatihanId/edit"
              params={{ pelatihanId }}
            >
              <Button
                variant="outline"
                size="sm"
                className="h-8 gap-1.5 border-[#E2E8F0] text-xs text-[#768094] hover:text-[#4D4D4D]"
              >
                <IconEdit className="size-3.5" />
                Edit
              </Button>
            </Link>
          </div>

          <div className="space-y-3">
            {[
              { label: "Judul", value: pelatihan.title },
              {
                label: "Deskripsi Singkat",
                value: pelatihan.shortDescription || "—",
              },
              {
                label: "Level",
                value:
                  pelatihan.level === "beginner"
                    ? "Pemula"
                    : pelatihan.level === "intermediate"
                      ? "Menengah"
                      : "Lanjutan",
              },
              { label: "Durasi", value: `${pelatihan.duration} jam` },
              {
                label: "Kapasitas",
                value: pelatihan.capacity
                  ? `${pelatihan.capacity} peserta`
                  : "Tidak terbatas",
              },
              {
                label: "Harga",
                value:
                  pelatihan.price === 0
                    ? "Gratis"
                    : new Intl.NumberFormat("id-ID", {
                        style: "currency",
                        currency: "IDR",
                        minimumFractionDigits: 0,
                      }).format(pelatihan.price),
              },
              {
                label: "Nilai Minimum Lulus",
                value: `${pelatihan.minimumScore}%`,
              },
              {
                label: "Instruktur",
                value: pelatihan.instructorName || "—",
              },
            ].map((row) => (
              <div
                key={row.label}
                className="flex gap-3 border-b border-slate-50 py-2 last:border-0"
              >
                <span className="w-[140px] shrink-0 text-xs font-medium text-[#768094]">
                  {row.label}
                </span>
                <span className="flex-1 text-xs font-semibold text-[#4D4D4D]">
                  {row.value}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Struktur Pembelajaran */}
        <div className="rounded-xl border border-[#E2E8F0] bg-white p-5 shadow-[0px_1px_2px_0px_rgba(15,23,42,0.04),0px_2px_6px_0px_rgba(15,23,42,0.06)]">
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-sm font-bold text-[#4D4D4D]">
              Struktur Pembelajaran
            </h3>
            <Link
              to="/back-office/pelatihan/$pelatihanId/materi"
              params={{ pelatihanId }}
              className="text-[10px] font-semibold text-[#1061D6] hover:underline"
            >
              Lihat Semua
            </Link>
          </div>

          <div className="max-h-[350px] space-y-2 overflow-y-auto pr-1">
            {flatMaterialsList.length === 0 ? (
              <p className="py-8 text-center text-xs font-semibold text-slate-400">
                Belum ada materi pembelajaran.
              </p>
            ) : (
              flatMaterialsList.slice(0, 5).map((mod, idx) => (
                <div
                  key={mod.id}
                  className="flex items-center gap-3 rounded-lg border border-slate-100 bg-slate-50/50 p-2.5 transition-colors hover:border-blue-100"
                >
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#1061D6]/10 text-[10px] font-bold text-[#1061D6]">
                    {idx + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p
                      className="truncate text-xs font-semibold text-[#4D4D4D]"
                      title={mod.title}
                    >
                      {mod.title}
                    </p>
                    <p className="mt-0.5 text-[10px] text-[#768094] capitalize">
                      {mod.type} · {mod.moduleTitle}
                    </p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Aktivitas Terbaru */}
      <div className="overflow-hidden rounded-xl border border-[#E2E8F0] bg-white shadow-[0px_1px_2px_0px_rgba(15,23,42,0.04),0px_2px_6px_0px_rgba(15,23,42,0.06)]">
        <div className="flex items-center justify-between border-b border-slate-100 px-5 py-4">
          <h3 className="text-sm font-bold text-[#4D4D4D]">
            Aktivitas Terbaru
          </h3>
          <Link
            to="/back-office/pelatihan/$pelatihanId/peserta"
            params={{ pelatihanId }}
          >
            <Button
              variant="outline"
              size="sm"
              className="h-8 gap-1.5 border-[#E2E8F0] text-xs text-[#768094] hover:text-[#4D4D4D]"
            >
              <IconEye className="size-3.5" />
              Lihat Semua
            </Button>
          </Link>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[700px] text-left">
            <thead>
              <tr className="border-b border-slate-100 bg-slate-50/50">
                <th className="w-8 px-5 py-3 text-xs font-semibold text-[#768094]">
                  No
                </th>
                <th className="px-5 py-3 text-xs font-semibold text-[#768094]">
                  Nama Peserta
                </th>
                <th className="px-5 py-3 text-xs font-semibold text-[#768094]">
                  Progress
                </th>
                <th className="px-5 py-3 text-xs font-semibold text-[#768094]">
                  Status
                </th>
                <th className="px-5 py-3 text-xs font-semibold text-[#768094]">
                  Terdaftar
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {stats.recentActivity.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    className="px-5 py-10 text-center text-xs font-semibold text-slate-400"
                  >
                    Belum ada aktivitas pendaftaran peserta.
                  </td>
                </tr>
              ) : (
                stats.recentActivity.map((row, i) => {
                  const badge =
                    statusBadge[row.status] ?? statusBadge.enrolled!;
                  return (
                    <tr
                      key={row.id}
                      className="transition-colors hover:bg-slate-50/50"
                    >
                      <td className="px-5 py-4 text-xs font-semibold text-[#768094]">
                        {i + 1}
                      </td>
                      <td className="px-5 py-4">
                        <p className="text-xs font-semibold text-[#4D4D4D]">
                          {row.name}
                        </p>
                        <p className="mt-0.5 text-[10px] text-[#768094]">
                          {row.email}
                        </p>
                      </td>
                      <td className="px-5 py-4">
                        <ProgressBar value={row.progress} />
                      </td>
                      <td className="px-5 py-4">
                        <span
                          className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${badge.cls}`}
                        >
                          {badge.label}
                        </span>
                      </td>
                      <td className="px-5 py-4 text-xs font-medium text-[#768094]">
                        {new Date(row.enrolledAt).toLocaleDateString("id-ID", {
                          day: "numeric",
                          month: "short",
                          year: "numeric",
                        })}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

